#!/usr/bin/env python3
"""Build the self-contained stdin diagnostic, keeping reviewed sources identical."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HEADER = '''#!/usr/bin/env python3
"""Generated by build_messenger_route_bundle.py; run through temporary SSH SOCKS.

Read-only host diagnosis followed by fixed-endpoint transport checks. No account
authentication, application configuration changes or third-party proxy services.
Each embedded source is separately reviewed and covered by its own tests.
"""
import sys

'''
FOOTER = '''

def run_source(source, name, compact=False):
    namespace = {"__name__": name}
    exec(compile(source, "<" + name + ">", "exec"), namespace)
    # Capture earlier scan attempts too; line/byte/time limits stay unchanged.
    if compact:
        namespace["LOG_WINDOW_MINUTES"] = 360
    original_args = sys.argv
    sys.argv = [name] + (["--compact"] if compact else [])
    try:
        return namespace["main"]()
    finally:
        sys.argv = original_args
        sys.stdout.flush()


def main():
    pairing_result = run_source(PAIRING_SOURCE, "pairing", compact=True)
    route_result = run_source(ROUTE_SOURCE, "route")
    return 0 if pairing_result == route_result == 0 else 1


if __name__ == "__main__":
    raise SystemExit(main())
'''


def render():
    return (HEADER + 'PAIRING_SOURCE = ' + repr((ROOT/'diagnose_whatsapp_pairing.py').read_text())
            + '\nROUTE_SOURCE = ' + repr((ROOT/'probe_messenger_via_mac.py').read_text()) + FOOTER)


if __name__ == '__main__':
    (ROOT/'diagnose_messenger_via_mac.py').write_text(render())
